function validate([s, p]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 100000) return 's needs 1 to 100000 characters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  if (typeof p !== 'string' || p.length < 2 || p.length > 100000) return 'p needs 2 to 100000 characters.';
  if (!/^[a-z*]+$/.test(p) || p.split('*').length !== 3) return 'p may contain only lowercase letters and exactly two * characters.';
  return null;
}

