function shortestMatchingSubstring(s, p) {
  const [head, middle, tail] = p.split('*');
  const starts = (part) => {
    const found = [];
    if (part.length === 0) {
      for (let i = 0; i <= s.length; i++) {
        found.push(i);
      }
      return found;
    }
    const fail = new Array(part.length).fill(0);
    for (let i = 1, k = 0; i < part.length; i++) {
      while (k > 0 && part[i] !== part[k]) {
        k = fail[k - 1];
      }
      if (part[i] === part[k]) {
        k++;
      }
      fail[i] = k;
    }
    for (let i = 0, k = 0; i < s.length; i++) {
      while (k > 0 && s[i] !== part[k]) {
        k = fail[k - 1];
      }
      if (s[i] === part[k]) {
        k++;
      }
      if (k === part.length) {
        found.push(i - k + 1);
        k = fail[k - 1];
      }
    }
    return found;
  };
  const heads = starts(head);
  const middles = starts(middle);
  const tails = starts(tail);
  let best = Infinity;
  let h = -1;
  let t = 0;
  for (const m of middles) {
    while (h + 1 < heads.length && heads[h + 1] + head.length <= m) {
      h++;
    }
    while (t < tails.length && tails[t] < m + middle.length) {
      t++;
    }
    if (h >= 0 && t < tails.length) {
      best = Math.min(best, tails[t] + tail.length - heads[h]);
    }
  }
  return best === Infinity ? -1 : best;
}

