function shortestMatchingSubstring(s, p) {
  // Try substrings from shortest to longest. A substring matches when it starts with the first piece, ends with
  // the last piece (without the two overlapping), and the part between them contains the middle piece.
  const [head, middle, tail] = p.split('*');
  for (let length = 0; length <= s.length; length++) {
    for (let i = 0; i + length <= s.length; i++) {
      const sub = s.slice(i, i + length);
      if (sub.length < head.length + tail.length || !sub.startsWith(head) || !sub.endsWith(tail)) continue;
      if (sub.slice(head.length, sub.length - tail.length).includes(middle)) return length;
    }
  }
  return -1;
}

