function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  // A tiny alphabet (1 to 3 letters) makes pieces occur often and overlap.
  const letters = 'abcdefghijklmnopqrstuvwxyz'.slice(pick(24)).slice(0, 1 + pick(3));
  const n = large ? 9000 + pick(1001) : 1 + pick(12);
  let s = '';
  for (let i = 0; i < n; i++) s += letters[pick(letters.length)];
  // Each piece is empty, copied from s (so it occurs), or random (so it may not).
  const piece = () => {
    const kind = rand();
    const length = large ? 1 + pick(rand() < 0.8 ? 6 : 300) : 1 + pick(3);
    if (kind < 0.2) return '';
    if (kind < 0.75) { const start = pick(Math.max(1, n - length + 1)); return s.slice(start, start + length); }
    let text = '';
    for (let i = 0; i < length; i++) text += letters[pick(letters.length)];
    return text;
  };
  return [s, `${piece()}*${piece()}*${piece()}`];
}
